  static int _repeating(int group, int base, int element) {
    if (group & 0xFF00 != base || group.isOdd || group & 0xFF > 0x1E) {
      throw ArgumentError.value(
          group, 'group', 'not a repeating group of ${base.toRadixString(16)}');
    }
    return group << 16 | element;
  }
